input.command:
cd /mnt/user-data/uploads && awk '
/asset = {/ { in_asset=1; cultures=""; regions=""; faiths=""; name=""; illust="" }
in_asset && /graphical_cultures/ { cultures=$0 }
in_asset && /graphical_regions/ { regions=$0 }
in_asset && /graphical_faiths/ { faiths=$0 }
in_asset && /name =/ { name=$0 }
in_asset && /illustration =/ { illust=$0 }
in_asset && /^[[:space:]]*}[[:space:]]*$/ { 
    in_asset=0
    if(cultures != "") print "CULTURE|" name "|" illust
    if(regions != "") print "REGION|" name "|" illust
    if(faiths != "") print "FAITH|" name "|" illust
}
' zz_00_temple_buildings_copy.txt | head -50

