            if current_tier not in assets:
                assets[current_tier] = {}
            continue

        # Detect asset block start
        if '\tasset = {' in line or '\t### ' in line:
            in_asset = True
            asset_buffer = []
            continue

        if in_asset:
            asset_buffer.append(line)

            # Detect asset block end
            if re.match(r'^\t}$', line):
                # Parse asset buffer
                asset_info = parse_asset_buffer(asset_buffer)
                if asset_info and current_tier:
                    gfx = asset_info.get('graphical_cultures')
                    faith = asset_info.get('faith', 'generic')

                    if gfx:
                        if gfx not in assets[current_tier]:
                            assets[current_tier][gfx] = {}
                        assets[current_tier][gfx][faith] = asset_info

                in_asset = False
                asset_buffer = []

    return assets

def parse_asset_buffer(buffer):
    """Parse asset buffer to extract info"""
    info = {}
    buffer_text = '\n'.join(buffer)

    # Extract graphical_cultures (first one only)
    cultures_match = re.search(r'graphical_cultures = \{ ([^\}]+) \}', buffer_text)
    if cultures_match:
        cultures = cultures_match.group(1).split()
        info['graphical_cultures'] = cultures[0]  # Take first one

    # Extract type
    type_match = re.search(r'type = (\w+)', buffer_text)
    if type_match:
        info['type'] = type_match.group(1)

    # Extract name
    name_match = re.search(r'name = "([^"]+)"', buffer_text)
    if name_match:
        info['name'] = name_match.group(1)

    # Extract illustration
    illust_match = re.search(r'illustration = (@illustration_\w+)', buffer_text)
    if illust_match:
        info['illustration'] = illust_match.group(1)

    # Extract soundeffect
    sound_match = re.search(r'soundeffect = \{ soundeffect = "([^"]+)" soundparameter', buffer_text)
    if sound_match:
        info['soundeffect'] = sound_match.group(1)

    # Extract tier from soundparameter
    tier_match = re.search(r'soundparameter = \{ "Tier" = (\d+) \}', buffer_text)
    if tier_match:
        info['tier_param'] = tier_match.group(1)

    # Detect faith
    if 'catholic_gfx' in buffer_text:
        info['faith'] = 'catholic'
    elif 'orthodox_gfx' in buffer_text:
        info['faith'] = 'orthodox'
    elif 'islamic_gfx' in buffer_text:
        info['faith'] = 'islamic'
    elif 'judaism_gfx' in buffer_text:
        info['faith'] = 'judaism'
    elif 'zoroastrian_gfx' in buffer_text:
        info['faith'] = 'zoroastrian'
    elif 'dharmic_gfx' in buffer_text:
        info['faith'] = 'dharmic'
    elif 'sinitic_gfx' in buffer_text:
        info['faith'] = 'sinitic'
    elif 'shinto_gfx' in buffer_text:
        info['faith'] = 'shinto'
    elif 'tengrism_gfx' in buffer_text:
        info['faith'] = 'tengrism'
    elif 'pagan_gfx' in buffer_text:
        info['faith'] = 'pagan'
    else:
        info['faith'] = 'generic'

    return info if info else None

